const CLOSED_STATUSES = ['concluído','concluido','finalizado','encerrado','encerrada','cancelado','cancelada','realizado','realizada','fechado','closed','done'];
const allTasks = $input.all().map(item => item.json);
const tasks = allTasks.filter(t => !CLOSED_STATUSES.includes(((t.status && t.status.status) || '').toLowerCase()));

// ── Helpers de custom field ──────────────────────────────────────────
function findField(task, pattern, type) {
  return (task.custom_fields || []).find(f => {
    const nameMatch = (f.name || '').toLowerCase().includes(pattern);
    return type ? (nameMatch && f.type === type) : nameMatch;
  });
}

// drop_down: value é um índice numérico dentro de type_config.options
function resolveDropdown(field) {
  if (!field || field.value === undefined || field.value === null) return null;
  const opts = (field.type_config && field.type_config.options) || [];
  const opt = opts[field.value];
  return opt ? opt.name : null;
}

// labels: value é um array de IDs de option, resolvido contra type_config.options[].label
function resolveLabels(field) {
  if (!field || !Array.isArray(field.value)) return [];
  const opts = (field.type_config && field.type_config.options) || [];
  return field.value
    .map(id => { const o = opts.find(o => o.id === id); return o ? o.label : null; })
    .filter(Boolean);
}

// tasks (relacionamento): value é array de tarefas vinculadas
function resolveRelatedId(field) {
  if (!field || !Array.isArray(field.value) || field.value.length === 0) return null;
  return field.value[0].id || null;
}

// date: value é epoch em ms (string ou número)
function resolveDate(value) {
  if (!value) return null;
  const ms = typeof value === 'string' ? parseInt(value, 10) : value;
  if (!ms) return null;
  return new Date(ms).toISOString().substring(0, 10);
}

// ── Mapas de label do ClickUp → chave do App (Task model) ────────────
const TASK_TYPE_MAP = {
  'criação/audiovisual': 'criacao',
  'setup/tracking': 'setup',
  'tráfego/performance': 'trafego',
  'web/dev': 'web',
  'estratégia/planejamento': 'estrategia',
  'reuniões/atendimento': 'reunioes',
  'administrativo/financeiro': 'administrativo',
};
const ORIGIN_MAP = {
  'onboarding': 'onboarding',
  'roadmap': 'roadmap',
  'ticket': 'ticket',
  'projeto': 'projeto',
};
const DESTINATION_MAP = {
  'publicação orgânica': 'publicacao_organica',
  'campanhas patrocinadas': 'campanhas_patrocinadas',
  'projeto web': 'projeto_web',
  'administrativo / financeiro': 'administrativo_financeiro',
  'envio / resposta para cliente': 'envio_resposta_cliente',
  'envio / resposta ao cliente': 'envio_resposta_cliente',
};
const APPROVAL_METHOD_MAP = {
  'aprova aí': 'aprovaaí',
  'whatsapp': 'whatsapp',
  'email': 'email',
};

// ── Anexos: viram uma seção em markdown no final da descrição ────────
function appendAttachments(description, attachments) {
  if (!attachments || attachments.length === 0) return description || '';
  const lines = attachments.map(a => `- ${a.title || 'arquivo'}: ${a.url}`);
  return (description || '').trim() + '\n\n--- Anexos ---\n' + lines.join('\n');
}

// project_id e list_id ficam SEMPRE null aqui de propósito - ver Sticky Note
// "Por que não linka Projeto automaticamente". O vínculo com Projeto é feito
// depois, manualmente, em lote, dentro do App.
const tasksPayload = tasks.map(t => {
  const clienteField = findField(t, 'cliente_relacionado');
  const clientClickupId = resolveRelatedId(clienteField);

  const tipoTarefaLabel = (resolveDropdown(findField(t, 'tipo de tarefa')) || '').toLowerCase();
  const taskType = TASK_TYPE_MAP[tipoTarefaLabel] || 'criacao';

  const origemLabel = (resolveDropdown(findField(t, 'origem')) || '').toLowerCase();
  const origin = ORIGIN_MAP[origemLabel] || 'projeto';

  const destinoLabels = resolveLabels(findField(t, 'destino'));
  const destination = DESTINATION_MAP[(destinoLabels[0] || '').toLowerCase()] || null;

  const situationLabel = resolveDropdown(findField(t, 'situa'));

  const metodoLabels = resolveLabels(findField(t, 'todo de aprova'));
  const approvalMethod = APPROVAL_METHOD_MAP[(metodoLabels[0] || '').toLowerCase()] || null;

  const aprovacaoInternaField = findField(t, 'interna');
  const internalApproval = !!(aprovacaoInternaField && aprovacaoInternaField.value);

  const dataAprovacaoField = findField(t, 'data de aprova');
  const approvalDate = resolveDate(dataAprovacaoField ? dataAprovacaoField.value : null);

  const dataPublicacaoField = findField(t, 'data de publica');
  const publishDate = resolveDate(dataPublicacaoField ? dataPublicacaoField.value : null);

  const requesterNameField = findField(t, 'solicitante', 'short_text');
  const requesterWhatsField = findField(t, 'solicitante', 'phone');

  return {
    clickup_task_id: t.id,
    project_id: null,
    list_id: null,
    client_clickup_id: clientClickupId,
    title: t.name,
    description: appendAttachments(t.description, t.attachments),
    clickup_status: (t.status && t.status.status) || 'backlog',
    clickup_priority: t.priority ? t.priority.priority : 'normal',
    task_type: taskType,
    origin: origin,
    destination: destination,
    situation: situationLabel,
    due_date: resolveDate(t.due_date),
    approval_date: approvalDate,
    publish_date: publishDate,
    approval_method: approvalMethod,
    internal_approval: internalApproval,
    is_ticket: origin === 'ticket',
    requester_name: requesterNameField ? requesterNameField.value : null,
    requester_whatsapp: requesterWhatsField ? requesterWhatsField.value : null,
    requester_channel: null,
    creator_email: t.creator ? t.creator.email : null,
    executor_email: (t.assignees && t.assignees[0]) ? t.assignees[0].email : null,
    responsavel_email: (t.assignees && t.assignees[1]) ? t.assignees[1].email : null,
    attachments: [],
    deleted: false,
  };
});

return [{ json: { tasks: tasksPayload } }];
